function d_hohmann(P,R){var mu=398600.4418,r1=P.r1_km||6678,r2=P.r2_km||42164;var a=(r1+r2)/2;var dv1=Math.sqrt(mu/r1)*(Math.sqrt(2*r2/(r1+r2))-1);var dv2=Math.sqrt(mu/r2)*(1-Math.sqrt(2*r1/(r1+r2)));var t=Math.PI*Math.sqrt(a*a*a/mu);return{dv1_kms:+dv1.toFixed(3),dv2_kms:+dv2.toFixed(3),total_dv_kms:+(dv1+dv2).toFixed(3),transfer_time_h:+(t/3600).toFixed(2)};}

